import { expect, test } from '@playwright/test';
import { RUN, api, openWithToken, registerUser, shot } from './realHelpers';

// Link embeds are generated by the server (SSRF-guarded unfurler), so this needs the server to reach the internet.
test('a link in a message gets a server-generated embed that the client renders', async ({ browser }) => {
  const o = await registerUser('em');
  const guild = await api<{ id: string }>(o.token, 'POST', '/guilds', { name: `Embeds ${RUN}` });
  const channels = await api<{ id: string; type: number }[]>(o.token, 'GET', `/guilds/${guild.id}/channels`);
  const text = channels.find(c => c.type === 0)!;
  await api(o.token, 'POST', `/channels/${text.id}/messages`, { content: 'https://example.com/' });
  const session = await openWithToken(browser, o.token, o.userId, o.username, `/channels/${guild.id}/${text.id}`);
  try {
    // the embed may arrive with a MESSAGE_UPDATE shortly after the message
    await expect(session.page.locator('.chat-embed-rich')).toContainText('Example Domain', { timeout: 20_000 });
    await shot(session.page, 'r31-link-embed');
  } finally {
    await session.ctx.close();
  }
});
